import { after } from 'next/server';

async function logAnalytics() {
  // Simulate an analytics service call
  await new Promise((resolve) => setTimeout(resolve, 500));
  console.log('Page view successfully logged to analytics service.');
}

export default function WelcomeComponent() {
  // Schedule the analytics logging to run after the response is sent to the client,
  // ensuring it does not block the initial page load.
  after(async () => {
    await logAnalytics();
  });

  return (
    <div>
      <h1>Welcome to our Application!</h1>
      <p>We are glad to have you here. Your visit has been noted without slowing down this page.</p>
    </div>
  );
}

